package com.Basics;

public class ArithmaticOperator {

	public static void main(String[] args) {
		// TODO Auto-generated method stub

		// 					Arithmetic Operator
//		----------------------------------------------------------------
		
		int a = 10;
		int b = 20;
		int add = a + b; // addition operator
		int sub = a - b; // subtraction operator
		int mul = a * b;
		int div = a / b;
		int mod = a % b;
		
		System.out.println(add+" "+sub+" "+mul+" "+div+" "+mod);
	}

}
